package com.gk.jobhelper.service;
import com.gk.jobhelper.common.*;import com.gk.jobhelper.dto.*;import com.gk.jobhelper.entity.*;import com.gk.jobhelper.mapper.*;import java.time.*;import java.util.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Service;import org.springframework.transaction.support.TransactionTemplate;
@Service public class RecruitmentPositionService {
 private final RecruitmentNoticeService notices;private final RecruitmentAttachmentMapper attachments;private final RecruitmentPositionMapper positions;private final RecruitmentAttachmentDownloadService downloader;private final List<RecruitmentPositionExtractor> extractors;private final HtmlRecruitmentPositionExtractor htmlExtractor;private final TransactionTemplate transactions;private final UserProfileMapper profiles;private final RecruitmentRequirementTextParser requirementParser=new RecruitmentRequirementTextParser();
 @Autowired public RecruitmentPositionService(RecruitmentNoticeService n,RecruitmentAttachmentMapper a,RecruitmentPositionMapper p,RecruitmentAttachmentDownloadService d,List<RecruitmentPositionExtractor> e,HtmlRecruitmentPositionExtractor h,TransactionTemplate t,UserProfileMapper u){notices=n;attachments=a;positions=p;downloader=d;extractors=e;htmlExtractor=h;transactions=t;profiles=u;}
 public RecruitmentPositionService(RecruitmentNoticeService n,RecruitmentAttachmentMapper a,RecruitmentPositionMapper p,RecruitmentAttachmentDownloadService d,List<RecruitmentPositionExtractor> e,HtmlRecruitmentPositionExtractor h,TransactionTemplate t){notices=n;attachments=a;positions=p;downloader=d;extractors=e;htmlExtractor=h;transactions=t;profiles=null;}
 public RecruitmentPositionExtractionResponse extract(Long noticeId){notices.detail(noticeId);List<RecruitmentAttachment> files=attachments.selectPositionDataByNoticeId(noticeId);if(files.isEmpty())throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"该公告没有可解析的岗位数据附件");int count=0,failed=0;for(RecruitmentAttachment file:files){try{DownloadedAttachment data=downloader.download(file);RecruitmentPositionExtractor extractor=extractors.stream().filter(e->e.supports(data.getFileType())).findFirst().orElseThrow(()->new BusinessException(ApiResponse.CODE_BAD_REQUEST,"暂不支持解析该岗位附件类型："+data.getFileType()));RecruitmentPositionExtractionResult result=extractor.extract(data,noticeId);if(result.positions.isEmpty())throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"附件未识别到结构可靠的岗位信息");for(RecruitmentPosition position:result.positions){if(position.getSourceType()==null)position.setSourceType("ATTACHMENT_"+data.getFileType());requirementParser.enrich(position);}transactions.execute(status->{positions.deleteByAttachmentId(file.getId());positions.insertBatch(result.positions);saveRequirements(result.positions);attachments.updateParseResult(file.getId(),data.getFileType(),"PARSED",null,result.positions.size(),LocalDateTime.now());return null;});count+=result.positions.size();}catch(Exception e){failed++;attachments.updateParseResult(file.getId(),file.getFileType(),status(e),safe(e.getMessage()),0,LocalDateTime.now());}}if(count==0&&failed>0)throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"岗位解析失败，请查看附件解析状态");return new RecruitmentPositionExtractionResponse(noticeId,files.size(),count,failed);}
 public RecruitmentPositionExtractionResponse extractBody(Long noticeId){RecruitmentNoticeVO notice=notices.detail(noticeId);if(!"FETCHED".equals(notice.getDetailStatus()))throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"请先获取公告详情");List<RecruitmentPosition> result=htmlExtractor.extract(notice.getBodyHtml(),notice.getBodyText(),noticeId);if(result.isEmpty())throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"公告正文未识别到结构可靠的岗位信息");for(RecruitmentPosition position:result)requirementParser.enrich(position);transactions.execute(status->{positions.deleteBodyByNoticeId(noticeId);positions.insertBatch(result);saveRequirements(result);return null;});return new RecruitmentPositionExtractionResponse(noticeId,0,result.size(),0);}
 public List<RecruitmentPositionVO> list(Long noticeId){notices.detail(noticeId);return positions.selectByNoticeId(noticeId);}public RecruitmentPositionLibraryPageVO page(String keyword,String location,String organization,String education,String major,Long noticeId,String matchStatus,int page,int size){int current=Math.max(1,page),pageSize=Math.min(100,Math.max(1,size));String k=like(keyword),l=like(location),o=like(organization),e=like(education),m="__LIMITED__".equals(major)?major:like(major);UserProfile profile=profiles==null?null:profiles.selectFirstProfile();Long profileId=profile==null?null:profile.getId();long total=positions.countLibrary(k,l,o,e,m,noticeId,profileId,matchStatus);return new RecruitmentPositionLibraryPageVO(total,current,pageSize,positions.selectLibrary(k,l,o,e,m,noticeId,profileId,matchStatus,(current-1)*pageSize,pageSize),positions.countLibraryNotices(k,l,o,e,m,noticeId,profileId,matchStatus),positions.selectLibraryLatestUpdatedAt());}public RecruitmentPositionVO detail(Long id){RecruitmentPositionVO p=positions.selectById(id);if(p==null)throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"招聘岗位不存在: "+id);p.setRequirements(positions.selectRequirementsByPositionId(id));return p;}
 public RecruitmentPositionFilterOptionsVO filterOptions(){RecruitmentPositionFilterOptionsVO vo=new RecruitmentPositionFilterOptionsVO();vo.setSources(positions.selectFilterSources());vo.setNotices(positions.selectFilterNotices());vo.setLocations(positions.selectFilterLocations());vo.setOrganizations(positions.selectFilterOrganizations());vo.setEducations(positions.selectFilterEducations());vo.setMajorTypes(positions.selectFilterMajorTypes());return vo;}
 private String like(String value){return value==null||value.trim().isEmpty()?null:"%"+value.trim()+"%";}private void saveRequirements(List<RecruitmentPosition> list){List<RecruitmentRequirement> all=new ArrayList<>();for(RecruitmentPosition p:list){add(all,p,"EDUCATION",p.getEducationRequirement());add(all,p,"DEGREE",p.getDegreeRequirement());add(all,p,"MAJOR",p.getMajorRequirement());add(all,p,"AGE",p.getAgeRequirement());add(all,p,"WORK_EXPERIENCE",p.getWorkYearsRequirement());add(all,p,"OTHER",p.getOtherRequirement());}if(!all.isEmpty())positions.insertRequirements(all);}
 private void add(List<RecruitmentRequirement> all,RecruitmentPosition p,String type,String raw){if(raw==null||raw.trim().isEmpty())return;RecruitmentRequirement r=new RecruitmentRequirement();r.setPositionId(p.getId());r.setRequirementType(type);r.setRequirementLevel(raw.contains("优先")?"PREFERRED":"REQUIRED");r.setRawText(raw);r.setSourceText(raw);r.setCreatedAt(LocalDateTime.now());all.add(r);}private String status(Exception exception){if(exception instanceof OcrRequiredException)return "OCR_REQUIRED";String message=exception.getMessage();return message!=null&&message.startsWith("暂不支持解析")?"UNSUPPORTED_FILE_TYPE":message!=null&&message.contains("未识别到结构可靠")?"NO_VALID_POSITION":"PARSE_FAILED";}private String safe(String message){if(message==null)return "岗位附件解析失败";return message.length()>450?message.substring(0,450):message;}
}
